-- Commission-only order processing for all Senior, Master and Expert badges.
-- Junior Trial continues to use Trial Bonus debits and its existing commission flow.

CREATE OR REPLACE FUNCTION public.member_submit_project_order(p_property_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := (select auth.uid());
    v_property public.properties%rowtype;
      v_level_unlocked boolean;
        v_set_unlocked boolean;
          v_commission_percent numeric(8,4);
            v_amount numeric(20,2);
              v_available numeric(20,2);
                v_holds numeric(20,2) := 0;
                  v_reserved numeric(20,2) := 0;
                    v_pending_orders numeric(20,2) := 0;
                      v_set_order_count integer := 0;
                        v_request_id uuid;
                          v_bonus_transaction_id uuid;
                            v_commission_transaction_id uuid;
                              v_commission_id uuid;
                                v_investment_id uuid;
                                  v_commission_amount numeric(20,2);
                                  begin
                                    if v_user_id is null then
                                        raise exception 'Sign in required' using errcode = '42501';
                                          end if;

                                            perform 1 from auth.users where id = v_user_id for update;
                                              perform pg_advisory_xact_lock(hashtextextended(v_user_id::text || ':OMR', 0));

                                                select * into v_property
                                                  from public.properties
                                                    where id = p_property_id and status = 'published'
                                                      for share;

                                                        if not found then raise exception 'This project is not currently available'; end if;
                                                          if v_property.project_level is null or v_property.set_number not between 1 and 3 then
                                                              raise exception 'This project is not assigned to a valid badge';
                                                                end if;
                                                                  if v_property.price_amount is null or v_property.price_amount <= 0 then
                                                                      raise exception 'The administrator has not set a confirmed OMR price for this project';
                                                                        end if;
                                                                          if v_property.project_level = 'Junior Trial' then
                                                                              if coalesce(cardinality(v_property.order_percentages), 0) < 1 then
                                                                                raise exception 'The administrator has not configured a commission percentage for this project';
                                                                              end if;
                                                                              select coalesce(v_property.order_percentages[1], 0)::numeric(8,4)
                                                                                into v_commission_percent;
                                                                            else
  -- Senior, Master and Expert orders do not debit or reserve customer wallet funds.
end if;

  insert into public.investment_requests(
                                                                                                                                                                                                                                                                                                                                                                                                                    user_id, property_id, property_name, plan_code, amount, currency,
                                                                                                                                                                                                                                                                                                                                                                                                                        commission_percent, expected_commission, note, status
                                                                                                                                                                                                                                                                                                                                                                                                                          ) values (
                                                                                                                                                                                                                                                                                                                                                                                                                              v_user_id, v_property.id, v_property.name, 'project_order', v_amount, 'OMR',
                                                                                                                                                                                                                                                                                                                                                                                                                                  v_commission_percent, round(v_amount * v_commission_percent / 100, 2),
                                                                                                                                                                                                                                                                                                                                                                                                                                      'Project order · Level: ' || v_property.project_level ||
                                                                                                                                                                                                                                                                                                                                                                                                                                            ' · Badge: ' || v_property.set_number::text ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                  ' · Commission: ' || v_commission_percent::text || '%',
                                                                                                                                                                                                                                                                                                                                                                                                                                                      case when v_property.project_level = 'Junior Trial'
                                                                                                                                                                                                                                                                                                                                                                                                                                                            then 'funded' else 'pending' end
                                                                                                                                                                                                                                                                                                                                                                                                                                                              ) returning id into v_request_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                if v_property.project_level = 'Junior Trial' then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    insert into public.trial_bonus_transactions(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          user_id, direction, amount, currency, reference_type, reference_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                idempotency_key, description, created_by
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) values (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          v_user_id, 'debit', v_amount, 'OMR',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'project_order', v_request_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'trial-bonus-order:' || v_request_id::text,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'Junior Trial property order: ' || v_property.name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_user_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ) returning id into v_bonus_transaction_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          insert into public.investments(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                user_id, property_id, amount, currency, status, reference,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      admin_note, approved_by, approved_at
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ) values (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                v_user_id, v_property.id, v_amount, 'OMR', 'funded',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'request:' || v_request_id::text, null, null, now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ) returning id into v_investment_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_commission_amount := round(v_amount * v_commission_percent / 100, 2);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if v_commission_amount > 0 then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        insert into public.commission_records(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                user_id, plan_id, commission_type, reference, base_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        commission_percent, amount, currency, status, description,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                idempotency_key, created_by, reviewed_by, reviewed_at, credited_at
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ) values (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_user_id, null, 'property',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'project-order:' || v_request_id::text,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_amount, v_commission_percent, v_commission_amount, 'OMR',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'credited', 'Junior Trial project order commission credited automatically',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'project-order-commission:' || v_request_id::text,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      v_user_id, v_user_id, now(), now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) returning id into v_commission_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  insert into public.wallet_transactions(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          user_id, transaction_type, direction, amount, currency, status,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  reference_type, reference_id, idempotency_key, description,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          created_by, metadata
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ) values (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v_user_id, 'commission', 'credit', v_commission_amount, 'OMR', 'posted',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'commission_record', v_commission_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'project-order-commission-credit:' || v_request_id::text,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'Junior Trial project order commission: ' || v_property.name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'investment_request_id', v_request_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'commission_percent', v_commission_percent
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ) returning id into v_commission_transaction_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        update public.commission_records
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              set wallet_transaction_id = v_commission_transaction_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    where id = v_commission_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            UPDATE public.investment_requests SET status = 'funded', funded_at = now() WHERE id = v_request_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        insert into public.financial_audit_log(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              actor_id, action, entity_type, entity_id, details
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ) values (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v_user_id, 'junior_trial_order_funded', 'investment_request',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_request_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'investment_id', v_investment_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'trial_bonus_transaction_id', v_bonus_transaction_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'commission_record_id', v_commission_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'commission_transaction_id', v_commission_transaction_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'amount', v_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'commission_amount', v_commission_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'currency', 'OMR'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return v_request_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $function$
;

CREATE OR REPLACE FUNCTION public.complete_badge_project_order_after_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_property public.properties%rowtype;
  v_investment_id uuid;
  v_commission_id uuid;
  v_commission_transaction_id uuid;
  v_commission_amount numeric(20,2);
begin
  if new.plan_code <> 'project_order'
     or new.status <> 'pending'
     or new.property_id is null
     or auth.uid() is distinct from new.user_id then
    return new;
  end if;

  select *
    into v_property
    from public.properties
   where id = new.property_id;

  if not found or v_property.project_level = 'Junior Trial' then
    return new;
  end if;

  if new.currency <> 'OMR' or new.amount <= 0 then
    raise exception 'Badge project orders must use a valid OMR amount';
  end if;

  -- Commission-only order: never debit the customer's project value.

  insert into public.investments (
    user_id, property_id, amount, currency, status, reference,
    admin_note, approved_by, approved_at
  ) values (
    new.user_id, v_property.id, new.amount, 'OMR', 'funded',
    'request:' || new.id::text, null, null, now()
  )
  returning id into v_investment_id;

  v_commission_amount := round(new.amount * coalesce(new.commission_percent, 0) / 100, 2);

  if v_commission_amount > 0 then
    insert into public.commission_records (
      user_id, plan_id, commission_type, reference, base_amount,
      commission_percent, amount, currency, status, description,
      idempotency_key, created_by, reviewed_by, reviewed_at, credited_at
    ) values (
      new.user_id, null, 'property',
      'project-order:' || new.id::text, new.amount,
      new.commission_percent, v_commission_amount, 'OMR', 'credited',
      'Commission-only badge property order commission credited automatically',
      'project-order-commission:' || new.id::text,
      new.user_id, new.user_id, now(), now()
    )
    returning id into v_commission_id;

    insert into public.wallet_transactions (
      user_id, transaction_type, direction, amount, currency, status,
      reference_type, reference_id, idempotency_key, description,
      created_by, metadata
    ) values (
      new.user_id, 'commission', 'credit', v_commission_amount, 'OMR', 'posted',
      'commission_record', v_commission_id,
      'project-order-commission-credit:' || new.id::text,
      'Badge property order commission: ' || v_property.name,
      new.user_id,
      jsonb_build_object('investment_request_id', new.id, 'commission_percent', new.commission_percent)
    )
    returning id into v_commission_transaction_id;

    update public.commission_records
       set wallet_transaction_id = v_commission_transaction_id
     where id = v_commission_id;
  end if;

  update public.investment_requests
     set status = 'funded',
         funded_at = now(),
         wallet_transaction_id = null
   where id = new.id;

  insert into public.financial_audit_log (
    actor_id, action, entity_type, entity_id, details
  ) values (
    new.user_id, 'badge_project_order_funded', 'investment_request', new.id,
    jsonb_build_object(
      'investment_id', v_investment_id,
      'commission_record_id', v_commission_id,
      'commission_transaction_id', v_commission_transaction_id,
      'amount', new.amount,
      'commission_amount', v_commission_amount,
      'currency', 'OMR',
      'project_level', v_property.project_level,
      'badge_number', v_property.set_number
    )
  );

  return new;
end;
$function$
;
